card_mod.style:
hui-generic-entity-row { padding: 4px 0px !important; }
hui-generic-entity-row:first-child { padding-top: 0px !important; }
hui-generic-entity-row:last-child { padding-bottom: 0px !important; }
ha-icon { fill: white !important; }

cards.styles:
.bubble-pop-up-background { background: #212529 !important; }
.bubble-pop-up-container { padding: 20px 20px calc(140px + var(--custom-height-offset-mobile)) 20px !important; margin-top: -30px !important; }
.bubble-header-container { height: 20px !important; padding-top: 0px !important; padding-bottom: 0px !important; }
.bubble-close-button { background: transparent !important; }

.navbar-card {
  border: none;
  background: rgba(33, 37, 41, 0.9);
  backdrop-filter: blur(4px);
  width: 100%;
  max-width: 500px;
  bottom: 0;
}
.button.active { background: transparent; }
.icon { fill: #ADB5BD !important; }
.icon.active { fill: #FFFFFF !important; }
ha-ripple { display: none !important; }

